def libertarian_paradox(freedom=100):
    if freedom > 100:
        freedom -= 50
    return freedom
print(libertarian_paradox())

def entangle(p1, p2):
    p2['state'] = p1['state']
    return p1, p2
particle1 = {'state': 'up'}
particle2 = {'state': 'down'}
print(entangle(particle1, particle2))

def algo_trade(prices):
    trades = []
    for price in prices:
        trades.append(price*1.001)
    return trades
print(algo_trade([100,101,102]))

